{"test_range": "tests/kernels/mhc/test_mhc_kernels.py:313-374", "module_conditions": ["DEVICE = current_platform.device_type", "requires_rocm_mhc_overlap = pytest.mark.skipif(not (_on_cdna4() and HAS_AITER_MHC_FUSED_POST_PRE_DELAYED_RMS_NORM), reason="gfx950 with AITER's fused delayed-seam kernel required")"], "decorators": ["pytest.mark.skipif(not HAS_TILELANG_MHC or not current_platform.is_device_capability_family(100), reason='SM100 TileLang mHC required')", "pytest.mark.parametrize('num_tokens', [0, 1, 8, 9, 32, 128, 256])", "pytest.mark.parametrize('entry', ['broadcast', 'identity', 'carried'])", "pytest.mark.parametrize('hidden_size,hc_mult', [(4096, 2), (5120, 4), (7168, 4)])"], "class_decorators": [], "module_guards": [], "supporting_classes": [], "input_and_call_source": "def test_deepseek_v41_mhc_overlap_preserves_outputs_on_replay(
    num_tokens, entry, hidden_size, hc_mult
):
    """The input is usable before joining; coefficients stay exact on graph replay."""
    from vllm.models.deepseek_v41.nvidia.ops.mhc import mhc_pre_delayed_overlap
    from vllm.utils.deep_gemm import is_deep_gemm_supported

    if not is_deep_gemm_supported():
        pytest.skip("DeepGEMM required")
    set_random_seed(42)
    mix_size = hc_mult * (hc_mult + 2)
    residual = torch.randn(
        num_tokens, hc_mult, hidden_size, dtype=torch.bfloat16, device=DEVICE
    )
    fn = torch.randn(mix_size, hc_mult, hidden_size, device=DEVICE) * 0.02
    x = None
    pre_mix = None
    if entry == "broadcast":
        x = residual[:, 0].contiguous()
        residual = x.unsqueeze(1).expand(-1, hc_mult, -1).contiguous()
        fn = fn.sum(1)
    else:
        fn = fn.flatten(1)
        if entry == "carried":
            pre_mix = torch.rand(num_tokens, hc_mult, device=DEVICE)
    scale = torch.tensor([0.5, 0.25, 1.0], device=DEVICE)
    base = torch.randn(mix_size, device=DEVICE)
    weight = torch.empty(hidden_size, dtype=torch.bfloat16, device=DEVICE).uniform_(
        0.5, 1.5
    )
    args = (residual, fn, scale, base, 1e-20, 1e-6, 1e-6, 2.0, 20)
    kwargs = dict(pre_mix=pre_mix, x=x, norm_weight=weight, norm_eps=1e-20)
    side = torch.cuda.Stream()

    def run():
        outputs = mhc_pre_delayed_overlap(*args, **kwargs, stream=side)
        consumed_input = outputs[2].clone()
        torch.cuda.current_stream().wait_stream(side)
        return (*outputs, consumed_input)

    def check(actual):
        expected = mhc_pre_delayed_tilelang(*args, **kwargs)
        for a, b in zip(actual[:4], expected, strict=True):
            torch.testing.assert_close(a, b, atol=0, rtol=0)
        torch.testing.assert_close(actual[4], expected[2], atol=0, rtol=0)

    check(run())
    if num_tokens == 0:
        return
    graph = torch.cuda.CUDAGraph()
    with torch.cuda.graph(graph):
        captured = run()
    for _ in range(5):
        if x is not None:
            x.normal_()
            residual.copy_(x.unsqueeze(1).expand_as(residual))
        else:
            residual.normal_()
        if pre_mix is not None:
            pre_mix.uniform_()
        graph.replay()
        check(captured)", "helpers": [], "implementation_anchors": ["vllm/model_executor/kernels/mhc/tilelang.py:61", "vllm/model_executor/kernels/mhc/tilelang.py:256", "vllm/model_executor/kernels/mhc/torch.py:6", "vllm/model_executor/layers/mhc.py:384", "vllm/models/deepseek_v41/nvidia/ops/mhc.py:60", "vllm/model_executor/kernels/mhc/triton.py:118", "vllm/models/deepseek_v41/amd/mhc.py:52", "vllm/models/deepseek_v41/amd/model.py:314", "vllm/models/deepseek_v41/nvidia/model.py:500", "vllm/models/deepseek_v41/nvidia/dspark.py:215", "vllm/models/deepseek_v4/nvidia/model.py:716", "vllm/models/deepseek_v4/nvidia/model.py:1220", "vllm/models/deepseek_v41/nvidia/ops/mega_mhc.py:47", "vllm/model_executor/kernels/mhc/triton.py:167", "vllm/_aiter_ops.py:5080"], "external_helper_anchors": [], "external_helper_sources": [], "validation": "仅静态源码核对，未导入或执行上游，未使用GPU"}

