    monkeypatch: pytest.MonkeyPatch,
) -> None:
    quant_config = ExpertsInt8Config()
    monkeypatch.setattr(
        fused_moe_utils.rocm_aiter_ops,
        "is_fusion_moe_shared_experts_enabled",
        lambda: True,
    )

    calls: list[tuple[object, str, str, str | None]] = []

    def check_compatibility(
        config: object,
        expert_prefix: str,
        shared_expert_prefix: str,
        moe_backend: str | None = None,
    ) -> tuple[bool, str | None]:
        calls.append((config, expert_prefix, shared_expert_prefix, moe_backend))
        return True, None

    monkeypatch.setattr(
        fused_moe_utils, "is_shared_expert_quant_fse_compatible", check_compatibility
    )

    assert fused_moe_utils.resolve_layer_fused_shared_expert(
        quant_config,
        "model.layers.0.mlp",
        shared_expert_name="shared_expert",
        moe_backend="aiter_mega_moe",
    )
    assert calls == [
        (
            quant_config,
            "model.layers.0.mlp.experts",
            "model.layers.0.mlp.shared_expert",
            "aiter_mega_moe",
        )
    ]", "helpers": [], "implementation_anchors": ["vllm/model_executor/layers/quantization/utils/config_utils.py:129", "vllm/model_executor/layers/fused_moe/utils.py:64", "vllm/models/deepseek_v4/amd/model.py:199", "vllm/model_executor/models/utils.py:525", "vllm/model_executor/models/qwen3_next.py:107", "vllm/_aiter_ops.py:2916", "vllm/models/glm5next/common/model.py:1422", "vllm/model_executor/layers/quantization/quark/quark.py:798", "vllm/model_executor/layers/fused_moe/layer.py:77"], "external_helper_anchors": [], "external_helper_sources": [], "validation": "仅静态源码核对，未导入或执行上游，未使用GPU"}

