    monkeypatch: pytest.MonkeyPatch,
    setting: str,
    value: object,
    reason: str | None,
) -> None:
    from vllm.models.glm5next.common import model as glm5_next_model

    parallel_config = SimpleNamespace(
        tensor_parallel_size=4,
        data_parallel_size=1,
        prefill_context_parallel_size=1,
        enable_expert_parallel=False,
    )
    on_gfx950 = value if setting == "on_gfx950" else True
    if setting != "on_gfx950":
        setattr(parallel_config, setting, value)
    monkeypatch.setattr("vllm.platforms.rocm.on_gfx950", lambda: on_gfx950)

    with patch.object(glm5_next_model.logger, "warning_once") as warning:
        tuned = glm5_next_model._fused_shared_experts_tuned(
            cast(ParallelConfig, parallel_config)
        )

    assert tuned is (reason is None)
    if reason is None:
        warning.assert_not_called()
    else:
        warning.assert_called_once()
        assert warning.call_args.args[1] == reason", "helpers": [], "implementation_anchors": ["vllm/model_executor/layers/quantization/utils/config_utils.py:129", "vllm/model_executor/layers/fused_moe/utils.py:64", "vllm/models/deepseek_v4/amd/model.py:199", "vllm/model_executor/models/utils.py:525", "vllm/model_executor/models/qwen3_next.py:107", "vllm/_aiter_ops.py:2916", "vllm/models/glm5next/common/model.py:1422", "vllm/model_executor/layers/quantization/quark/quark.py:798", "vllm/model_executor/layers/fused_moe/layer.py:77"], "external_helper_anchors": [], "external_helper_sources": [], "validation": "仅静态源码核对，未导入或执行上游，未使用GPU"}

