    exclude_shared_expert: bool,
) -> None:
    """Unrelated online targets preserve the checkpoint's FSE decision."""
    shared_prefix = "model.layers.0.mlp.shared_expert"
    quant_config = QuarkConfig(
        {
            **_QUARK_FSE_CONFIG,
            "exclude": (
                [f"{shared_prefix}.down_proj"] if exclude_shared_expert else []
            ),
        }
    )
    quant_config.online_quantization_config = OnlineQuantizationConfig(
        QuantizationConfigArgs(targets={"*linear_attn.out_proj": "mxfp4"})
    )

    compatible, reason = is_shared_expert_quant_fse_compatible(
        quant_config,
        "model.layers.0.mlp.experts",
        shared_prefix,
    )

    assert compatible is not exclude_shared_expert
    assert reason == (
        f"Quark excludes shared experts at {shared_prefix}"
        if exclude_shared_expert
        else None
    )", "helpers": [], "implementation_anchors": ["vllm/model_executor/layers/quantization/utils/config_utils.py:129", "vllm/model_executor/layers/fused_moe/utils.py:64", "vllm/models/deepseek_v4/amd/model.py:199", "vllm/model_executor/models/utils.py:525", "vllm/model_executor/models/qwen3_next.py:107", "vllm/_aiter_ops.py:2916", "vllm/models/glm5next/common/model.py:1422", "vllm/model_executor/layers/quantization/quark/quark.py:798", "vllm/model_executor/layers/fused_moe/layer.py:77"], "external_helper_anchors": [], "external_helper_sources": [], "validation": "仅静态源码核对，未导入或执行上游，未使用GPU"}

