    class BranchKernel(VllmJitKernel["BranchKernel.CompileKey"]):
        @dataclass(frozen=True)
        class CompileKey:
            value: int

        def dispatch(self, *, value: int) -> CompileKey:  # type: ignore[override]
            if value > 0:
                value = 1
            return self.CompileKey(value=value)

        def get_warmup_keys(self) -> list[CompileKey]:
            return []

        def compile(self, compile_key: CompileKey) -> None:
            pass

    class KwargsReturnKernel(VllmJitKernel["KwargsReturnKernel.CompileKey"]):
        @dataclass(frozen=True)
        class CompileKey:
            value: int

        def dispatch(self, *, value: int) -> CompileKey:  # type: ignore[override]
            return self.CompileKey(**{"value": value})

        def get_warmup_keys(self) -> list[CompileKey]:
            return []

        def compile(self, compile_key: CompileKey) -> None:
            pass

    with pytest.raises(ValueError, match="local assignments"):
        BranchKernel()
    with pytest.raises(
        ValueError,
        match=r"may unpack only its own \*\*kwargs parameter once",
    ):
        KwargsReturnKernel()", "helpers": [], "implementation_anchors": ["vllm/model_executor/warmup/jit_warmup.py:105", "vllm/model_executor/warmup/jit_warmup.py:561", "vllm/model_executor/warmup/jit_warmup.py:651", "vllm/model_executor/warmup/jit_warmup.py:1008", "vllm/model_executor/warmup/jit_warmup_triton_helper.py:135"], "external_helper_anchors": [], "external_helper_sources": [], "validation": "仅静态源码核对，未导入或执行上游，未使用GPU"}

