    topk = torch.arange(sum(counts) * 2, dtype=torch.int32).reshape(-1, 2)
    ctx = _forward_context(
        dp_metadata=DPMetadata(
            num_tokens_across_dp_cpu=torch.tensor(counts), local_sizes=local_sizes
        )
    )
    with (
